// Okresy raportu + stałe. Wszystkie daty w Europe/Warsaw.
const tz = 'Europe/Warsaw';
const now = DateTime.now().setZone(tz);
const today = now.startOf('day');
const monday = today.minus({ days: today.weekday - 1 }); // poniedziałek bieżącego tygodnia
const d = (x) => x.toISODate();

// Pełny tydzień pon–nd (GA4, WooCommerce, Meta)
const wCurS = monday.minus({ days: 7 });
const wCurE = monday.minus({ days: 1 });
const wPrevS = monday.minus({ days: 14 });
const wPrevE = monday.minus({ days: 8 });

// Search Console: 7 dni kończące się 3 dni temu (opóźnienie danych) vs poprzednie 7 dni
const gEnd = today.minus({ days: 3 });
const gStart = gEnd.minus({ days: 6 });
const gPrevEnd = gEnd.minus({ days: 7 });
const gPrevStart = gEnd.minus({ days: 13 });

const site = 'https://lunae.pl';
const inspect = [
  { url: site + '/', kind: 'new' },
  { url: site + '/sklep/', kind: 'new' },
  { url: site + '/kategoria-produktu/bielizna/biustonosze/', kind: 'new' },
  { url: site + '/produkt/biustonosz-iris-incarnata/', kind: 'product' },
  { url: site + '/pl/p/Biustonosz-Iris-incarnata/7', kind: 'old' },
  { url: site + '/pl/c/Bielizna/1', kind: 'old' },
];

return [{
  json: {
    tz,
    generatedAt: now.toISO(),
    site,
    gscSite: 'sc-domain:lunae.pl',
    gscSiteEnc: encodeURIComponent('sc-domain:lunae.pl'),
    ga4Property: '<GA4_PROPERTY_ID>',
    metaAccount: 'act_<AD_ACCOUNT_ID>',
    metaCampaign: '<CAMPAIGN_ID>',
    graphVersion: 'v27.0',
    metaSpendCapZl: 1500,
    wooBase: site + '/wp-json/wc/v3',
    gsc: {
      cur: { start: d(gStart), end: d(gEnd) },
      prev: { start: d(gPrevStart), end: d(gPrevEnd) },
    },
    week: {
      cur: { start: d(wCurS), end: d(wCurE) },
      prev: { start: d(wPrevS), end: d(wPrevE) },
    },
    // WooCommerce: after/before w strefie sklepu (Europe/Warsaw), oba tygodnie w jednym zapytaniu
    wooAfter: d(wPrevS) + 'T00:00:00',
    wooBefore: d(monday) + 'T00:00:00',
    metaTimeRanges: JSON.stringify([
      { since: d(wCurS), until: d(wCurE) },
      { since: d(wPrevS), until: d(wPrevE) },
    ]),
    metaTimeRangeCur: JSON.stringify({ since: d(wCurS), until: d(wCurE) }),
    inspect,
  },
}];

// Składa raport tygodniowy (3 embedy Discord). Każde źródło jest opcjonalne:
// błąd lub brak danych => "brak danych: <źródło>", raport i tak wychodzi.
const C = $('Okresy i konfiguracja').first().json;
const NB = ' ';
const MONTHS = ['sty', 'lut', 'mar', 'kwi', 'maj', 'cze', 'lip', 'sie', 'wrz', 'paź', 'lis', 'gru'];
const missing = [];

// ---------- helpers ----------
function safeAll(name) {
  try { return $(name).all().map((i) => i.json || {}); } catch (e) { return null; }
}
function errMsg(er) {
  if (er == null) return 'nieznany błąd';
  if (typeof er === 'string') return er;
  let m = er.message || er.description || er.error || '';
  if (typeof m === 'object') m = m.message || JSON.stringify(m);
  const code = er.httpCode || er.status || er.code || '';
  if (code && !String(m).includes(String(code))) m = code + ' ' + m;
  return m || JSON.stringify(er).slice(0, 110);
}
function short(s, n) { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
// Zwraca { data, err }: data = lista itemów bez błędów; err = tekst gdy całe źródło padło.
function source(name) {
  const items = safeAll(name);
  if (items === null) return { data: [], err: 'węzeł się nie wykonał' };
  const ok = items.filter((j) => !j.error);
  const bad = items.find((j) => j.error);
  if (!ok.length && bad) return { data: [], err: short(errMsg(bad.error), 110) };
  return { data: ok, err: null };
}
function num(x) { const n = Number(x); return Number.isFinite(n) ? n : 0; }
function group(s) { return s.replace(/\B(?=(\d{3})+(?!\d))/g, NB); }
function fInt(n) { const r = Math.round(num(n)); return (r < 0 ? '−' : '') + group(String(Math.abs(r))); }
function fDec(n, dg) { if (dg === undefined) dg = 1; const v = num(n); const p = Math.abs(v).toFixed(dg).split('.'); return (v < 0 ? '−' : '') + group(p[0]) + (dg ? ',' + p[1] : ''); }
function fZl(n) { return fDec(n, 2) + NB + 'zł'; }
function fPct(ratio, dg) { return fDec(num(ratio) * 100, dg === undefined ? 1 : dg) + NB + '%'; }
function ratio(a, b) { return num(b) ? num(a) / num(b) : 0; }
// Zmiana względna: ▲ +12% / ▼ −5% / = / ▲ nowe
function dRel(cur, prev) {
  cur = num(cur); prev = num(prev);
  if (!prev && !cur) return '=';
  if (!prev) return '▲ nowe';
  const p = (cur - prev) / prev;
  if (Math.abs(p) < 0.005) return '=';
  return (p > 0 ? '▲ +' : '▼ ') + fDec(p * 100, 0) + '%';
}
// Zmiana w punktach procentowych (ratio 0..1)
function dPp(cur, prev) {
  const diff = (num(cur) - num(prev)) * 100;
  if (Math.abs(diff) < 0.05) return '=';
  return (diff > 0 ? '▲ +' : '▼ ') + fDec(diff, 1) + NB + 'pp';
}
// Pozycja: mniejsza = lepsza. ▲ = awans, ▼ = spadek.
function dPos(cur, prev) {
  cur = num(cur); prev = num(prev);
  if (!cur || !prev) return '';
  const diff = prev - cur;
  if (Math.abs(diff) < 0.05) return '=';
  return (diff > 0 ? '▲ awans o ' : '▼ spadek o ') + fDec(Math.abs(diff), 1);
}
function dZlAbs(cur, prev) { return dRel(cur, prev) + ' (było ' + fZl(prev) + ')'; }
function dayLabel(iso) { const [y, m, d] = iso.split('-').map(Number); return d + NB + MONTHS[m - 1]; }
function rangeLabel(r) {
  const [y1, m1, d1] = r.start.split('-').map(Number);
  const [y2, m2, d2] = r.end.split('-').map(Number);
  if (y1 === y2 && m1 === m2) return d1 + '–' + d2 + NB + MONTHS[m2 - 1];
  return d1 + NB + MONTHS[m1 - 1] + ' – ' + d2 + NB + MONTHS[m2 - 1];
}
function shortDate(iso) { if (!iso) return '—'; const dt = DateTime.fromISO(iso).setZone(C.tz); return dt.isValid ? dt.toFormat('d.LL') : '—'; }
function path(url) {
  let p = String(url || '').replace(/^https?:\/\/(www\.)?lunae\.pl/, '') || '/';
  try { p = decodeURI(p); } catch (e) {}
  return short(p, 48);
}
// Pole embeda: max 1024 znaki, ucinamy całe linie.
function field(name, lines, inline) {
  let out = '';
  for (const l of lines) {
    if ((out + l + '\n').length > 1000) { out += '…'; break; }
    out += l + '\n';
  }
  return { name: short(name, 250), value: out.trim() || '—', inline: !!inline };
}
function noData(src, err) { missing.push(src); return 'brak danych: ' + src + (err ? ' (' + err + ')' : ''); }

// ---------- Search Console ----------
const seoLines = [];
const seoFields = [];
let seoPartial = false;
{
  const daily = source('GSC · dzienne sumy');
  if (daily.err) {
    seoLines.push(noData('Search Console', daily.err));
    seoPartial = true;
  } else {
    const rows = (daily.data[0] && daily.data[0].rows) || [];
    const agg = (r) => {
      const sel = rows.filter((x) => x.keys && x.keys[0] >= r.start && x.keys[0] <= r.end);
      const clicks = sel.reduce((s, x) => s + num(x.clicks), 0);
      const impr = sel.reduce((s, x) => s + num(x.impressions), 0);
      const posW = sel.reduce((s, x) => s + num(x.position) * num(x.impressions), 0);
      return { clicks, impr, ctr: ratio(clicks, impr), pos: impr ? posW / impr : 0, days: sel.length };
    };
    const c = agg(C.gsc.cur);
    const p = agg(C.gsc.prev);
    seoLines.push('**' + rangeLabel(C.gsc.cur) + '** vs ' + rangeLabel(C.gsc.prev) + ' (GSC ma ~3 dni opóźnienia)');
    seoLines.push('Kliknięcia **' + fInt(c.clicks) + '** ' + dRel(c.clicks, p.clicks) + ' (było ' + fInt(p.clicks) + ')');
    seoLines.push('Wyświetlenia **' + fInt(c.impr) + '** ' + dRel(c.impr, p.impr) + ' (było ' + fInt(p.impr) + ')');
    seoLines.push('CTR **' + fPct(c.ctr) + '** ' + dPp(c.ctr, p.ctr));
    seoLines.push('Śr. pozycja **' + (c.pos ? fDec(c.pos, 1) : '—') + '** ' + dPos(c.pos, p.pos) + (p.pos ? ' (było ' + fDec(p.pos, 1) + ')' : ''));
    if (c.days < 7) seoLines.push('_dane za ' + c.days + ' z 7 dni_');
  }

  const rowsOf = (name) => { const s = source(name); return { err: s.err, rows: (s.data[0] && s.data[0].rows) || [] }; };
  const qc = rowsOf('GSC · frazy (bieżący)');
  const qp = rowsOf('GSC · frazy (poprzedni)');
  const pc = rowsOf('GSC · strony (bieżący)');
  const pp = rowsOf('GSC · strony (poprzedni)');
  const sortTop = (rows) => rows.slice().sort((a, b) => num(b.clicks) - num(a.clicks) || num(b.impressions) - num(a.impressions));
  const toMap = (rows) => { const m = {}; for (const r of rows) m[r.keys[0]] = r; return m; };

  if (qc.err) { seoFields.push(field('Top frazy', [noData('Search Console · frazy', qc.err)])); seoPartial = true; }
  else {
    const pm = qp.err ? null : toMap(qp.rows);
    const lines = sortTop(qc.rows).slice(0, 10).map((r, i) => {
      const prev = pm && pm[r.keys[0]];
      const dl = pm ? ' ' + (prev ? dRel(r.clicks, prev.clicks) : 'nowa') : '';
      return (i + 1) + '. „' + short(r.keys[0], 40) + '” ' + fInt(r.clicks) + ' / ' + fInt(r.impressions) + ' · poz. ' + fDec(r.position, 1) + dl;
    });
    seoFields.push(field('Top frazy (kliknięcia / wyświetlenia)', lines.length ? lines : ['brak fraz w tym okresie']));
  }
  if (pc.err) { seoFields.push(field('Top strony', [noData('Search Console · strony', pc.err)])); seoPartial = true; }
  else {
    const pm = pp.err ? null : toMap(pp.rows);
    const lines = sortTop(pc.rows).slice(0, 10).map((r, i) => {
      const prev = pm && pm[r.keys[0]];
      const dl = pm ? ' ' + (prev ? dRel(r.clicks, prev.clicks) : 'nowa') : '';
      return (i + 1) + '. `' + path(r.keys[0]) + '` ' + fInt(r.clicks) + ' / ' + fInt(r.impressions) + ' · poz. ' + fDec(r.position, 1) + dl;
    });
    seoFields.push(field('Top strony (kliknięcia / wyświetlenia)', lines.length ? lines : ['brak stron w tym okresie']));
  }

  // Wzrosty / spadki kliknięć (frazy + strony)
  const movers = [];
  const addMovers = (cur, prev, kind) => {
    if (cur.err || prev.err) return;
    const cm = toMap(cur.rows); const pm = toMap(prev.rows);
    const keys = new Set([...Object.keys(cm), ...Object.keys(pm)]);
    for (const k of keys) {
      const dc = num(cm[k] && cm[k].clicks) - num(pm[k] && pm[k].clicks);
      if (dc) movers.push({ kind, key: k, dc, cur: num(cm[k] && cm[k].clicks), prev: num(pm[k] && pm[k].clicks) });
    }
  };
  addMovers(qc, qp, 'fraza');
  addMovers(pc, pp, 'strona');
  const label = (m) => (m.kind === 'fraza' ? '„' + short(m.key, 36) + '”' : '`' + path(m.key) + '`') + ' ' + fInt(m.prev) + ' → ' + fInt(m.cur);
  if (qc.err || qp.err || pc.err || pp.err) {
    if (!qc.err && !pc.err) { seoFields.push(field('Wzrosty / spadki', ['niepełne dane z poprzedniego okresu'])); }
  } else {
    const up = movers.filter((m) => m.dc > 0).sort((a, b) => b.dc - a.dc).slice(0, 5).map((m) => '▲ +' + fInt(m.dc) + ' ' + label(m));
    const down = movers.filter((m) => m.dc < 0).sort((a, b) => a.dc - b.dc).slice(0, 5).map((m) => '▼ ' + fInt(m.dc) + ' ' + label(m));
    seoFields.push(field('Wzrosty kliknięć', up.length ? up : ['brak'], true));
    seoFields.push(field('Spadki kliknięć', down.length ? down : ['brak'], true));
  }

  // Sitemapy
  const sm = source('GSC · sitemapy');
  let shoperSitemaps = 0;
  if (sm.err) { seoFields.push(field('Sitemapy', [noData('Search Console · sitemapy', sm.err)])); seoPartial = true; }
  else {
    const list = (sm.data[0] && sm.data[0].sitemap) || [];
    const lines = list.map((s) => {
      const isShoper = /GoogleSitemap|\/console\//.test(s.path || '');
      if (isShoper) shoperSitemaps++;
      const urls = (s.contents || []).filter((x) => x.type === 'web').reduce((a, x) => a + num(x.submitted), 0);
      const name = isShoper ? 'Shoper (stara)' : '`' + path(s.path) + '`';
      const prob = num(s.errors) || num(s.warnings) ? ' · **błędy ' + fInt(s.errors) + ' / ostrz. ' + fInt(s.warnings) + '**' : ' · 0 błędów';
      return name + ' · pobrana ' + shortDate(s.lastDownloaded) + ' · ' + fInt(urls) + ' URL' + prob + (s.isPending ? ' · oczekuje' : '');
    });
    if (!list.some((s) => /wp-sitemap\.xml/.test(s.path || ''))) lines.push('**wp-sitemap.xml nie jest zgłoszona!**');
    seoFields.push(field('Sitemapy', lines.length ? lines : ['brak zgłoszonych sitemap']));
  }

  // Inspekcja URL (opcjonalna)
  const insp = safeAll('GSC · inspekcja URL');
  if (insp === null || !insp.length) {
    seoFields.push(field('Indeksacja', [noData('URL Inspection', 'węzeł się nie wykonał')]));
  } else {
    const lines = [];
    let oldRedirect = 0; let oldTotal = 0; let failed = 0; let lastErr = '';
    C.inspect.forEach((u, i) => {
      const j = insp[i] || {};
      if (j.error || !j.inspectionResult) { failed++; lastErr = short(errMsg(j.error), 80); return; }
      const r = j.inspectionResult;
      const ix = r.indexStatusResult || {};
      const mark = ix.verdict === 'PASS' ? '✓' : ix.verdict === 'FAIL' ? '✗' : '·';
      let line = mark + ' `' + path(u.url) + '` ' + short(ix.coverageState || ix.verdict || '?', 60);
      if (ix.lastCrawlTime) line += ' · crawl ' + shortDate(ix.lastCrawlTime);
      if (u.kind === 'old') {
        oldTotal++;
        if (/przekierow|redirect/i.test(ix.coverageState || '') || ix.verdict !== 'PASS') oldRedirect++;
      }
      if (u.kind === 'product') {
        const rr = r.richResultsResult;
        if (rr && rr.detectedItems && rr.detectedItems.length) {
          const types = rr.detectedItems.map((x) => x.richResultType).join(', ');
          line += '\n  wyniki rozszerzone: ' + short(types, 70) + ' → ' + (rr.verdict === 'PASS' ? 'OK' : rr.verdict === 'FAIL' ? '**błędy**' : rr.verdict || '?');
        } else {
          line += '\n  wyniki rozszerzone: nie wykryto';
        }
      }
      if (ix.googleCanonical && ix.userCanonical && ix.googleCanonical !== ix.userCanonical && u.kind !== 'old') {
        line += '\n  kanoniczny Google: `' + path(ix.googleCanonical) + '`';
      }
      lines.push(line);
    });
    if (failed === C.inspect.length) {
      lines.length = 0;
      lines.push(noData('URL Inspection', lastErr));
    } else if (failed) {
      lines.push('_' + failed + ' URL bez wyniku (' + lastErr + ')_');
    }
    const oldExpected = C.inspect.filter((u) => u.kind === 'old').length;
    if (shoperSitemaps && oldExpected && oldTotal === oldExpected && oldRedirect === oldExpected) {
      lines.push('Stare adresy Shopera Google widzi już jako przekierowanie → można usunąć ' + shoperSitemaps + ' sitemapy Shopera w GSC.');
    } else if (shoperSitemaps) {
      lines.push('Sitemapy Shopera nadal zgłoszone (' + shoperSitemaps + ') — usunąć, gdy stare /pl/ URL-e będą „przekierowaniem”.');
    }
    seoFields.push(field('Indeksacja (URL Inspection)', lines));
  }
}

// ---------- GA4 ----------
const trafficLines = [];
const trafficFields = [];
let trafficPartial = false;
let ga4 = null;
{
  const g = source('GA4 · raporty');
  const reports = (g.data[0] && g.data[0].reports) || null;
  if (g.err || !reports) {
    trafficLines.push(noData('GA4', g.err || 'pusta odpowiedź'));
    trafficPartial = true;
  } else {
    const parse = (rep) => {
      const dh = (rep.dimensionHeaders || []).map((h) => h.name);
      const mh = (rep.metricHeaders || []).map((h) => h.name);
      return (rep.rows || []).map((row) => {
        const dims = {}; const m = {};
        dh.forEach((n, i) => { dims[n] = row.dimensionValues[i].value; });
        mh.forEach((n, i) => { m[n] = num(row.metricValues[i].value); });
        return { dims, m };
      });
    };
    const tot = parse(reports[0] || {});
    const pick = (rows, range) => (rows.find((r) => (r.dims.dateRange || 'cur') === range) || { m: {} }).m;
    const c = pick(tot, 'cur'); const p = pick(tot, 'prev');
    ga4 = { c, p };
    trafficLines.push('**GA4** · ' + rangeLabel(C.week.cur) + ' vs ' + rangeLabel(C.week.prev));
    trafficLines.push('Sesje **' + fInt(c.sessions) + '** ' + dRel(c.sessions, p.sessions) + ' · użytkownicy **' + fInt(c.totalUsers) + '** ' + dRel(c.totalUsers, p.totalUsers));
    trafficLines.push('Zakupy (GA4) **' + fInt(c.ecommercePurchases) + '** ' + dRel(c.ecommercePurchases, p.ecommercePurchases) + ' · przychód **' + fZl(c.purchaseRevenue) + '** ' + dRel(c.purchaseRevenue, p.purchaseRevenue));
    trafficLines.push('Konwersja (zakupy / sesje) **' + fPct(ratio(c.ecommercePurchases, c.sessions), 2) + '** ' + dPp(ratio(c.ecommercePurchases, c.sessions), ratio(p.ecommercePurchases, p.sessions)));

    const ch = parse(reports[1] || {});
    const byCh = {};
    for (const r of ch) {
      const k = r.dims.sessionDefaultChannelGroup || '(brak)';
      byCh[k] = byCh[k] || { cur: {}, prev: {} };
      byCh[k][(r.dims.dateRange || 'cur') === 'prev' ? 'prev' : 'cur'] = r.m;
    }
    const totalPurch = num(c.ecommercePurchases);
    const chLines = Object.entries(byCh)
      .sort((a, b) => num(b[1].cur.sessions) - num(a[1].cur.sessions))
      .slice(0, 8)
      .map(([k, v]) => {
        const pu = num(v.cur.ecommercePurchases);
        return k + ' **' + fInt(v.cur.sessions) + '** ' + dRel(v.cur.sessions, v.prev.sessions) +
          (pu ? ' · zak. ' + fInt(pu) + (totalPurch ? ' (' + fPct(pu / totalPurch, 0) + ')' : '') : '');
      });
    trafficFields.push(field('Kanały (sesje · zakupy, udział w zakupach)', chLines.length ? chLines : ['brak sesji']));

    const lp = parse(reports[2] || {});
    const lpLines = lp.slice(0, 5).map((r, i) => (i + 1) + '. `' + path(r.dims.landingPage || r.dims.landingPagePlusQueryString) + '` ' + fInt(r.m.sessions) + ' ses.' + (r.m.ecommercePurchases ? ' · ' + fInt(r.m.ecommercePurchases) + ' zak.' : ''));
    trafficFields.push(field('Strony wejścia (top 5)', lpLines.length ? lpLines : ['brak danych w tym okresie']));
  }
}

// ---------- WooCommerce ----------
let woo = null;
{
  const w = source('Woo · zamówienia');
  if (w.err) {
    trafficFields.push(field('Sklep (WooCommerce)', [noData('WooCommerce', w.err)]));
    trafficPartial = true;
  } else {
    const orders = w.data.filter((o) => o && o.id);
    const inRange = (o, r) => { const dd = String(o.date_created || '').slice(0, 10); return dd >= r.start && dd <= r.end; };
    const value = (o) => num(o.total) + (o.refunds || []).reduce((s, x) => s + num(x.total), 0); // refunds.total są ujemne
    const sum = (r) => { const sel = orders.filter((o) => inRange(o, r)); return { n: sel.length, rev: sel.reduce((s, o) => s + value(o), 0) }; };
    const c = sum(C.week.cur); const p = sum(C.week.prev);
    woo = { c, p, capped: orders.length >= 100 };
    const lines = [
      'Zamówienia opłacone **' + fInt(c.n) + '** ' + dRel(c.n, p.n) + ' (było ' + fInt(p.n) + ')',
      'Przychód brutto **' + fZl(c.rev) + '** ' + dZlAbs(c.rev, p.rev),
      'Śr. koszyk **' + (c.n ? fZl(c.rev / c.n) : '—') + '**' + (p.n ? ' (było ' + fZl(p.rev / p.n) + ')' : ''),
    ];
    if (ga4) {
      const g = ga4.c.ecommercePurchases || 0;
      if (g < c.n) lines.push('GA4 zarejestrował ' + fInt(g) + ' z ' + fInt(c.n) + ' zamówień (zgody cookies / blokery)');
      else if (g > c.n) lines.push('GA4: ' + fInt(g) + ' zakupy vs ' + fInt(c.n) + ' opłacone w sklepie (np. testowe / nieopłacone zamówienia)');
      else lines.push('GA4 zgodny ze sklepem (' + fInt(g) + ')');
    }
    if (woo.capped) lines.push('_≥100 zamówień w 2 tyg. — wynik może być niepełny_');
    trafficFields.unshift(field('Sklep (WooCommerce, processing + completed)', lines));
  }
}

