    adsLines.push('CPC (link) **' + (a.clicks ? fZl(a.spend / a.clicks) : '—') + '**' + (b.clicks ? ' (było ' + fZl(b.spend / b.clicks) + ')' : ''));
    adsLines.push('Zakupy wg Meta **' + fInt(a.purch) + '** (' + fZl(a.value) + ') ' + dRel(a.purch, b.purch) + (a.spend ? ' · ROAS Meta ' + fDec(ratio(a.value, a.spend), 2) : ''));
    if (woo) {
