// ---------- Discord ----------
const COLORS = { seo: 0x4f7cac, traffic: 0x5f9e7a, ads: 0xb5677d, warn: 0xd9a400 };
const ts = DateTime.now().toUTC().toISO();
const embeds = [
  { title: 'SEO · Google Search Console', color: seoPartial ? COLORS.warn : COLORS.seo, description: seoLines.join('\n'), fields: seoFields, timestamp: ts },
  { title: 'Ruch i sprzedaż · GA4 + WooCommerce', color: trafficPartial ? COLORS.warn : COLORS.traffic, description: trafficLines.join('\n'), fields: trafficFields, timestamp: ts },
  { title: 'Reklamy · Meta', color: adsPartial ? COLORS.warn : COLORS.ads, description: adsLines.join('\n'), fields: adsFields,
    footer: { text: 'Zakupy wg Meta są niepełne (piksel) — decyzje opieraj na ROAS blended.' }, timestamp: ts },
];
// Limity Discorda: description ≤ 4096, ≤ 25 pól, łącznie ≤ 6000 znaków.
const clip = (t, n) => (t.length > n ? t.slice(0, n - 1) + '…' : t);
for (const e of embeds) { e.description = clip(e.description, 4000) || '—'; e.fields = e.fields.slice(0, 25); }
const size = () => embeds.reduce((s, e) => s + e.title.length + e.description.length + (e.footer ? e.footer.text.length : 0) + e.fields.reduce((a, f) => a + f.name.length + f.value.length, 0), 0);
while (size() > 5900) {
  const biggest = embeds.flatMap((e) => e.fields).sort((a, b) => b.value.length - a.value.length)[0];
  if (!biggest || biggest.value.length < 120) break;
  const lines = biggest.value.split('\n');
  biggest.value = lines.slice(0, Math.max(1, lines.length - 2)).join('\n') + '\n…';
}

